(6058164, 891373, 96751, '<td valign="top">Lovely lines, accentuated by the b/w processing.</td>', 'Lovely lines, accentuated by the b/w processing.', '2010-06-16 01:44:39.000000', NULL, 1),
(6058167, 891512, 116574, '<td valign="top">DNMC</td>', 'DNMC', '2010-06-16 01:44:53.000000', NULL, 1),
(6058169, 891836, 96751, '<td valign="top">There is something a bit murky about this image, although I like the use of negative space.</td>', 'There is something a bit murky about this image, although I like the use of negative space.', '2010-06-16 01:44:59.000000', NULL, 1),
