(6058340, 890568, 5822, '<td valign="top">Boy, what slick processing. Quite painterly. Topaz Simplify? Impressive. The boat looks less affected by the filter though. Can it still be considered a photograph?</td>', 'Boy, what slick processing. Quite painterly. Topaz Simplify? Impressive. The boat looks less affected by the filter though. Can it still be considered a photograph?', '2010-06-16 03:04:37.000000', NULL, 1),
(6058347, 891562, 5822, '<td valign="top">Where''s the SS Waldo? Nice sky and I like the B&amp;W but contrast is a smidgen too high.</td>', 'Where''s the SS Waldo? Nice sky and I like the B&W but contrast is a smidgen too high.', '2010-06-16 03:08:32.000000', NULL, 1),
