(6058932, 891755, 114225, '<td valign="top">Great catch with the boats all aligned so that you could get a leading line. I kind of wish I could make out the people on the boat more, but that''s not too much of a hinderance.</td>', 'Great catch with the boats all aligned so that you could get a leading line. I kind of wish I could make out the people on the boat more, but that''s not too much of a hinderance.', '2010-06-16 10:57:02.000000', NULL, 1),
(6058934, 891191, 114225, '<td valign="top">I''m torn on the tone mapping use. It makes the scene much more interesting, but it feels almost too un-natual to me.</td>', 'I''m torn on the tone mapping use. It makes the scene much more interesting, but it feels almost too un-natual to me.', '2010-06-16 10:57:54.000000', NULL, 1),
(6058939, 891623, 114225, '<td valign="top">Good take on this challenge. To me, it tells an upcoming story of someone who will soon jump into the canoe. Also, great details everywhere, including in the water.</td>', 'Good take on this challenge. To me, it tells an upcoming story of someone who will soon jump into the canoe. Also, great details everywhere, including in the water.', '2010-06-16 10:58:42.000000', NULL, 1),
(6058943, 891550, 114225, '<td valign="top">To me, this photo begins to tell a story, but to continue the story, I feel I need even more context (e.g. wider crop so I can see more of the surroundings).</td>', 'To me, this photo begins to tell a story, but to continue the story, I feel I need even more context (e.g. wider crop so I can see more of the surroundings).', '2010-06-16 10:59:34.000000', NULL, 1),
(6058944, 891438, 114225, '<td valign="top">I think the duo-tone effect really work here. I like the story you are telling with going from city to rural.</td>', 'I think the duo-tone effect really work here. I like the story you are telling with going from city to rural.', '2010-06-16 11:00:10.000000', NULL, 1),
(6058945, 891738, 114225, '<td valign="top">This is a photo I could see being used on a postcard or promotional brochure. Nice splash of color along with good details in the foreground.</td>', 'This is a photo I could see being used on a postcard or promotional brochure. Nice splash of color along with good details in the foreground.', '2010-06-16 11:01:00.000000', NULL, 1),
(6058947, 890668, 114225, '<td valign="top">What a peaceful scene, with just a little movement from the boat causing some ripples to add a bit more interest to the photo. I like that the boat is slightly diagonal as well.</td>', 'What a peaceful scene, with just a little movement from the boat causing some ripples to add a bit more interest to the photo. I like that the boat is slightly diagonal as well.', '2010-06-16 11:03:07.000000', NULL, 1),
(6058948, 891676, 114225, '<td valign="top">Great story here. Very good colors (mood) for this type of photo.</td>', 'Great story here. Very good colors (mood) for this type of photo.', '2010-06-16 11:03:28.000000', NULL, 1),
(6058949, 891351, 114225, '<td valign="top">Cute. Good execution on the shot (clarity and catching bubbles). Doesn''t hold a ton of interest for me.</td>', 'Cute. Good execution on the shot (clarity and catching bubbles). Doesn''t hold a ton of interest for me.', '2010-06-16 11:04:17.000000', NULL, 1),
