(6065950, 891836, 39343, '<td valign="top">A really intriguing image - that looming wall and mysterious feel work well for me.</td>', 'A really intriguing image - that looming wall and mysterious feel work well for me.', '2010-06-22 15:29:38.000000', NULL, 1),
(6065953, 890978, 39343, '<td valign="top">Really unique composition - I quite like the mood of this image, the feeling of beginning a long journey to sea...</td>', 'Really unique composition - I quite like the mood of this image, the feeling of beginning a long journey to sea...', '2010-06-22 15:31:28.000000', NULL, 1),
(6065954, 891801, 39343, '<td valign="top">Great color and overall mood - I like the touch of the water on the dock - gives a sense of human presence to the image.</td>', 'Great color and overall mood - I like the touch of the water on the dock - gives a sense of human presence to the image.', '2010-06-22 15:31:31.000000', NULL, 1),
(6065956, 891385, 39343, '<td valign="top">Love the light on the main and the shadows on the jib.  Great composition as well with the lighthouse.</td>', 'Love the light on the main and the shadows on the jib.  Great composition as well with the lighthouse.', '2010-06-22 15:33:21.000000', NULL, 1),
(6065958, 891845, 39343, '<td valign="top">I really like the texture on the hull as well as the contrast between that and the orderly line of sailboats in the background.  Great color, too!</td>', 'I really like the texture on the hull as well as the contrast between that and the orderly line of sailboats in the background.  Great color, too!', '2010-06-22 15:34:28.000000', NULL, 1),
(6065960, 891755, 39343, '<td valign="top">Great race shot - I like t he repetition of the spinnakers down the line - especially down the left side of the frame.</td>', 'Great race shot - I like t he repetition of the spinnakers down the line - especially down the left side of the frame.', '2010-06-22 15:35:40.000000', NULL, 1),
(6065966, 891510, 39343, '<td valign="top">Great peaceful mood captured here - love the stillness of the water.  Is this Bayswater Marina?</td>', 'Great peaceful mood captured here - love the stillness of the water.  Is this Bayswater Marina?', '2010-06-22 15:39:28.000000', NULL, 1),
(6065967, 891104, 39343, '<td valign="top">Fantastic detail in the water spray - great sense of (small scale) speed!</td>', 'Fantastic detail in the water spray - great sense of (small scale) speed!', '2010-06-22 15:40:07.000000', NULL, 1),
(6065969, 891554, 39343, '<td valign="top">Very inviting image - love the color!</td>', 'Very inviting image - love the color!', '2010-06-22 15:40:57.000000', NULL, 1),
(6065972, 891667, 39343, '<td valign="top">A nice peaceful feeling of night in the marina - well captured.  I like how the moon is just peeking through the rigging!</td>', 'A nice peaceful feeling of night in the marina - well captured.  I like how the moon is just peeking through the rigging!', '2010-06-22 15:42:14.000000', NULL, 1),
(6065975, 891404, 39343, '<td valign="top">Fantastic sky - really gives the image a nice sense of depth.</td>', 'Fantastic sky - really gives the image a nice sense of depth.', '2010-06-22 15:43:08.000000', NULL, 1),
(6065978, 891583, 39343, '<td valign="top">I''m usually not a big fan of HDR, but I gotta say, you''ve managed to create a rather foreboding sky - love the detail that you''ve brought out.</td>', 'I''m usually not a big fan of HDR, but I gotta say, you''ve managed to create a rather foreboding sky - love the detail that you''ve brought out.', '2010-06-22 15:45:01.000000', NULL, 1),
(6065980, 890560, 39343, '<td valign="top">Great timing!  I can really feel the storm in this image - the gray tones of the sky and water, the blur from the rain and the sense of the ship straining at her mooring.</td>', 'Great timing!  I can really feel the storm in this image - the gray tones of the sky and water, the blur from the rain and the sense of the ship straining at her mooring.', '2010-06-22 15:46:37.000000', NULL, 1),
(6065991, 891392, 39343, '<td valign="top">This is great - love the perspective and composition!</td>', 'This is great - love the perspective and composition!', '2010-06-22 16:07:25.000000', NULL, 1),
(6065998, 891732, 39343, '<td valign="top">Beautiful boat, but the the composition is a bit awkward to me - the boat is just too crowded in the upper corner of the frame...</td>', 'Beautiful boat, but the the composition is a bit awkward to me - the boat is just too crowded in the upper corner of the frame...', '2010-06-22 16:10:08.000000', NULL, 1),
(6065999, 891586, 39343, '<td valign="top">Nice concept - perhaps a blue background would have given it a bit more punch?</td>', 'Nice concept - perhaps a blue background would have given it a bit more punch?', '2010-06-22 16:11:13.000000', NULL, 1),
(6066002, 891285, 39343, '<td valign="top">I like the concept, but the image seems a bit flat to me - something like this really needs to be more dynamic - perhaps a more extreme angle and more interesting and dramatic background.</td>', 'I like the concept, but the image seems a bit flat to me - something like this really needs to be more dynamic - perhaps a more extreme angle and more interesting and dramatic background.', '2010-06-22 16:12:32.000000', NULL, 1),
(6066003, 891604, 39343, '<td valign="top">One of the few images in the challenge taken on a boat!  I would have liked to have seen more of the boat though - really bring it in as a subject rather than just parts hovering at the bottom of the frame.</td>', 'One of the few images in the challenge taken on a boat!  I would have liked to have seen more of the boat though - really bring it in as a subject rather than just parts hovering at the bottom of the frame.', '2010-06-22 16:14:00.000000', NULL, 1),
(6066005, 891758, 39343, '<td valign="top">This one managed to put a smile on my face. :)</td>', 'This one managed to put a smile on my face. :)', '2010-06-22 16:15:03.000000', NULL, 1),
(6066027, 891511, 117912, '<td valign="top">Beautiful composition, elegant use of negative space.</td>', 'Beautiful composition, elegant use of negative space.', '2010-06-22 16:42:09.000000', NULL, 1),
(6066028, 891554, 117912, '<td valign="top">Wonderful colors - very peaceful.</td>', 'Wonderful colors - very peaceful.', '2010-06-22 16:43:11.000000', NULL, 1),
(6066029, 891586, 117912, '<td valign="top">Beautiful composition - must have taken a while to make all the origami boats.</td>', 'Beautiful composition - must have taken a while to make all the origami boats.', '2010-06-22 16:44:35.000000', NULL, 1),
(6066168, 891590, 117636, '<td valign="top"><u></u></td>', '', '2010-06-22 18:37:10.000000', NULL, 1),
(6066191, 891740, 39343, '<td valign="top">Great shot - I think it really embodies a nice sunny summer weekend afternoon on the water.  I even think the flare works - I can almost feel the hot sun beating down...</td>', 'Great shot - I think it really embodies a nice sunny summer weekend afternoon on the water.  I even think the flare works - I can almost feel the hot sun beating down...', '2010-06-22 19:13:25.000000', NULL, 1),
(6066198, 891693, 39343, '<td valign="top">I like the mood of this image a lot.  There is a peaceful feeling, yet at the same time with the clouds and all the boats pointing into the wind, there is a sense of an incoming squall - the calm before the storm, so to speak.</td>', 'I like the mood of this image a lot.  There is a peaceful feeling, yet at the same time with the clouds and all the boats pointing into the wind, there is a sense of an incoming squall - the calm before the storm, so to speak.', '2010-06-22 19:16:46.000000', NULL, 1),
(6066200, 891847, 39343, '<td valign="top">Great light and sky!  There is something wonderfully ominous about the empty dingy that just seems to be drifting around out there.  I think that feeling would be enhanced even more with the deletion of the other boat up near the horizon.</td>', 'Great light and sky!  There is something wonderfully ominous about the empty dingy that just seems to be drifting around out there.  I think that feeling would be enhanced even more with the deletion of the other boat up near the horizon.', '2010-06-22 19:19:25.000000', NULL, 1),
(6066202, 891264, 39343, '<td valign="top">Great color and angle - I really like the looming presence of the old hull!</td>', 'Great color and angle - I really like the looming presence of the old hull!', '2010-06-22 19:20:17.000000', NULL, 1),
(6066206, 891191, 39343, '<td valign="top">Interesting image, but I''m just really not a big fan of the really heavy HDR...</td>', 'Interesting image, but I''m just really not a big fan of the really heavy HDR...', '2010-06-22 19:22:56.000000', NULL, 1),
(6066209, 891674, 39343, '<td valign="top">Certainly meets the challenge, however my eye really has no focus to go to - perhaps a tighter crop with more focus on the tug would strengthen the image.</td>', 'Certainly meets the challenge, however my eye really has no focus to go to - perhaps a tighter crop with more focus on the tug would strengthen the image.', '2010-06-22 19:24:27.000000', NULL, 1),
(6066213, 891469, 39343, '<td valign="top">Great silhouettes!  I think my favorite part of this image, though, is how the sea just blurs up into the sky with no horizon line - like they are one.  Really interesting color up at the top of the frame as well.</td>', 'Great silhouettes!  I think my favorite part of this image, though, is how the sea just blurs up into the sky with no horizon line - like they are one.  Really interesting color up at the top of the frame as well.', '2010-06-22 19:26:38.000000', NULL, 1),
(6066299, 891189, 39343, '<td valign="top">Really nice composition - I like how the bridge in the background compliments the wreck.  The colors are a bit odd and harsh, though - especially the plants...</td>', 'Really nice composition - I like how the bridge in the background compliments the wreck.  The colors are a bit odd and harsh, though - especially the plants...', '2010-06-22 20:32:13.000000', NULL, 1),
(6066315, 891648, 39343, '<td valign="top">Another of the rare actually on the boat entries for this challenge!  Nice detail in the wake - the flag is a nice added touch as well.</td>', 'Another of the rare actually on the boat entries for this challenge!  Nice detail in the wake - the flag is a nice added touch as well.', '2010-06-22 20:48:41.000000', NULL, 1),
(6066320, 890993, 39343, '<td valign="top">I think this is an interesting shot, but the overall grayness of the image make it really flat.</td>', 'I think this is an interesting shot, but the overall grayness of the image make it really flat.', '2010-06-22 20:51:26.000000', NULL, 1),
(6066323, 891678, 39343, '<td valign="top">I like the subject a lot, but the composition doesn''t quite do it for me.  I think a closer crop would on the bow and wheelhouse would be stronger - there''s just too much going on at the top of the frame.</td>', 'I like the subject a lot, but the composition doesn''t quite do it for me.  I think a closer crop would on the bow and wheelhouse would be stronger - there''s just too much going on at the top of the frame.', '2010-06-22 20:53:23.000000', NULL, 1),
(6066326, 890711, 39343, '<td valign="top">That''s a very interesting vessel, but I think I don''t think the angle is very interesting - perhaps a closer crop or more of a detail type shot would help.</td>', 'That''s a very interesting vessel, but I think I don''t think the angle is very interesting - perhaps a closer crop or more of a detail type shot would help.', '2010-06-22 20:55:04.000000', NULL, 1),
(6066329, 891729, 39343, '<td valign="top">The boat gets pretty lost in the background - I find my attention drawn much more to the trees in the foreground than anything else.</td>', 'The boat gets pretty lost in the background - I find my attention drawn much more to the trees in the foreground than anything else.', '2010-06-22 20:55:54.000000', NULL, 1),
(6066331, 891512, 39343, '<td valign="top">Nice angle - I like his distant gaze as well.</td>', 'Nice angle - I like his distant gaze as well.', '2010-06-22 20:56:42.000000', NULL, 1),
(6066332, 891233, 39343, '<td valign="top">I''d have to say this is my favorite of the paper boat entries.  I like the perspective of the shot and the detail of the water.</td>', 'I''d have to say this is my favorite of the paper boat entries.  I like the perspective of the shot and the detail of the water.', '2010-06-22 20:57:49.000000', NULL, 1),
(6066334, 891751, 39343, '<td valign="top">She looks like a beauty!  Would love to have seen more of the boat!</td>', 'She looks like a beauty!  Would love to have seen more of the boat!', '2010-06-22 20:59:56.000000', NULL, 1),
(6066361, 890915, 114969, '<td valign="top">It is actually quite easy to miss the "ghost kayak"; the exposure may be a bit too long here to really appreciate the action. Nice reflections though, I''m sure there is a nice potential here on a sunny day.</td>', 'It is actually quite easy to miss the "ghost kayak"; the exposure may be a bit too long here to really appreciate the action. Nice reflections though, I''m sure there is a nice potential here on a sunny day.', '2010-06-22 21:24:07.000000', NULL, 1),
(6066406, 891675, 51747, '<td valign="top">Great perspective and outstanding in B&amp;W</td>', 'Great perspective and outstanding in B&W', '2010-06-22 21:51:08.000000', NULL, 1);
