(6066599, 891255, 117494, '<td valign="top">Beautiful picture! Beautiful girl! Though, might be better if she is off the center (to the left perhaps...)</td>', 'Beautiful picture! Beautiful girl! Though, might be better if she is off the center (to the left perhaps...)', '2010-06-22 23:54:42.000000', NULL, 1),
(6066606, 891149, 117494, '<td valign="top">Nice work on colors and composition!</td>', 'Nice work on colors and composition!', '2010-06-22 23:58:54.000000', NULL, 1),
(6066614, 891653, 117494, '<td valign="top">Sweet diagonal!</td>', 'Sweet diagonal!', '2010-06-23 00:02:45.000000', NULL, 1),
