(6066675, 891754, 39057, '<td valign="top">I''ll give you two extra points for jumping out of the box. 8</td>', 'I''ll give you two extra points for jumping out of the box. 8', '2010-06-23 00:27:27.000000', NULL, 1),
(6066678, 891575, 39057, '<td valign="top">Could this be the winner? Some very good shots in the show. This one may or may not score high. I give it a 10 though.</td>', 'Could this be the winner? Some very good shots in the show. This one may or may not score high. I give it a 10 though.', '2010-06-23 00:29:27.000000', NULL, 1),
