INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6163840, 891837, 98339, '<td valign="top">love the tones in this!!!  I have one of some colored canoes that were getting ready to be repaired...like this it''s one of my favorites...</td>', 'love the tones in this!!!  I have one of some colored canoes that were getting ready to be repaired...like this it''s one of my favorites...', '2010-09-16 09:56:54.000000', NULL, 0),
(6163997, 891837, 96751, '<td valign="top">The tones and the metallics are great!  I wonder if you got these with a photo filter or through channel mixing?</td>', 'The tones and the metallics are great!  I wonder if you got these with a photo filter or through channel mixing?', '2010-09-16 13:28:22.000000', NULL, 0),
(6164009, 891837, 33361, '<td valign="top">Thank you both! I used Nik Silver Efex and the sepia filter. I played with the levels a bit. The boats were an ugly gray, but the warmth added a lot to improve the image. ; )</td>', 'Thank you both! I used Nik Silver Efex and the sepia filter. I played with the levels a bit. The boats were an ugly gray, but the warmth added a lot to improve the image. ; )', '2010-09-16 13:37:05.000000', NULL, 0),
(6240535, 891351, 123348, '<td valign="top">That is sooo beautiful!</td>', 'That is sooo beautiful!', '2010-12-01 15:05:56.000000', NULL, 0),
(6274566, 891732, 54645, '<td valign="top">I don''t mind crowding and snipping sails, etc; however, it is a rather flat composition. No real, or percieved movement. A boat sailing &lt; stopped motion&gt; in the same plane as the horizon with out a second or third element to create a visual tension made for a flat scene.  Cheers, Ben<br/> <br/>ETA: Go Aggies!<br/><br/><i>Message edited by author 2011-01-07 00:27:34.</i></td>', 'I don''t mind crowding and snipping sails, etc; however, it is a rather flat composition. No real, or percieved movement. A boat sailing < stopped motion> in the same plane as the horizon with out a second or third element to create a visual tension made for a flat scene.  Cheers, Ben ETA: Go Aggies!', '2011-01-07 00:19:51.000000', '2011-01-07 00:27:34.000000', 0),
(6295902, 890710, 119747, '<td valign="top">Just looking back over my favourites and REALLY like this one. It means something to me as my favourite place to go in summer has a harbour similar to this and it reminds me of it.</td>', 'Just looking back over my favourites and REALLY like this one. It means something to me as my favourite place to go in summer has a harbour similar to this and it reminds me of it.', '2011-01-27 17:10:36.000000', NULL, 0),
(6461741, 890710, 96751, '<td valign="top">Brilliant. In every sense of the world.</td>', 'Brilliant. In every sense of the world.', '2011-07-05 12:01:17.000000', NULL, 0),
(6461780, 890710, 69008, '<td valign="top">This is a grabber of a shot. It  was fortunate that the current  has the boats lined up the way they are to "watch" the sunrise.  I also notice the light shining through the windows of the buildings.</td>', 'This is a grabber of a shot. It  was fortunate that the current  has the boats lined up the way they are to "watch" the sunrise.  I also notice the light shining through the windows of the buildings.', '2011-07-05 13:11:02.000000', NULL, 0),
(6731125, 891510, 69008, '<td valign="top">This is a pretty scene. When shooting jpg night shots where there are the orange lights, I generally switch to "tungsten/incandescent" WB, or dial in a WB around 2700 K to get a nice blue sky.  <br/>With the orange lighting, this one does look natural though.</td>', 'This is a pretty scene. When shooting jpg night shots where there are the orange lights, I generally switch to "tungsten/incandescent" WB, or dial in a WB around 2700 K to get a nice blue sky.  With the orange lighting, this one does look natural though.', '2012-04-03 11:53:15.000000', NULL, 0);
COMMIT;
